This Terraform configuration uses the AWS provider to look up the latest official Amazon Linux 2 AMI published by Amazon in the selected AWS region. It outputs the AMI ID, name, owner, and creation date so it can be used by other Terraform configurations or EC2 instances.

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region where the latest Amazon Linux 2 AMI should be looked up."
  type        = string
  default     = "us-east-1"
}

data "aws_ami" "latest_amazon_linux_2" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name = "name"
    values = [
      "amzn2-ami-hvm-*-x86_64-gp2"
    ]
  }

  filter {
    name = "architecture"
    values = [
      "x86_64"
    ]
  }

  filter {
    name = "virtualization-type"
    values = [
      "hvm"
    ]
  }

  filter {
    name = "root-device-type"
    values = [
      "ebs"
    ]
  }

  filter {
    name = "state"
    values = [
      "available"
    ]
  }
}

